// Extract incoming payload safely
const raw = $input.first().json;
const body = (raw && raw.body) ? raw.body : raw;
const rawPhone = String((body && (body.phone || body.from || (body.message && body.message.from ? body.message.from.id : null))) || '9829012345');
const text = String((body && (body.text || body.message_text || (body.message ? body.message.text : '') || body.description)) || '');
const lat = (body && body.lat) ? Number(body.lat) : 26.9124;
const lon = (body && body.lon) ? Number(body.lon) : 75.7873;
const channel = (body && (body.channel || (body.message ? 'telegram' : 'whatsapp'))) || 'whatsapp';
const chatId = (body && body.message && body.message.chat) ? body.message.chat.id : null;

// Salted Phone Hash (Privacy Compliance)
let cleanDigits = rawPhone.replace(/\D/g, '') || '9829012345';
if (cleanDigits.length === 12 && cleanDigits.startsWith('91')) { cleanDigits = cleanDigits.substring(2); } else if (cleanDigits.length === 11 && cleanDigits.startsWith('0')) { cleanDigits = cleanDigits.substring(1); }
const saltStr = cleanDigits + ':neerdrishti-default-salt-2026';
const crypto = require('crypto');
const hexHash = crypto.createHash('sha256').update(saltStr).digest('hex');
const reporterHash = 'sha256:' + hexHash.substring(0, 32);

// Detect Language Script
let detectedLang = 'en';
let sarvamCode = 'hi-IN';
if (/[\u0900-\u097F]/.test(text)) { detectedLang = 'hi'; sarvamCode = 'hi-IN'; }
else if (/[\u0B80-\u0BFF]/.test(text)) { detectedLang = 'ta'; sarvamCode = 'ta-IN'; }
else if (/[\u0C80-\u0CFF]/.test(text)) { detectedLang = 'kn'; sarvamCode = 'kn-IN'; }
else if (/[\u0C00-\u0C7F]/.test(text)) { detectedLang = 'te'; sarvamCode = 'te-IN'; }
else if (/[\u0D00-\u0D7F]/.test(text)) { detectedLang = 'ml'; sarvamCode = 'ml-IN'; }
else if (/[\u0A80-\u0AFF]/.test(text)) { detectedLang = 'gu'; sarvamCode = 'gu-IN'; }
else if (/[\u0980-\u09FF]/.test(text)) { detectedLang = 'bn'; sarvamCode = 'bn-IN'; }

return [{
  json: {
    channel,
    chat_id: chatId,
    reporter_hash: reporterHash,
    incoming_text: text,
    detected_language: detectedLang,
    sarvam_language_code: sarvamCode,
    is_regional: detectedLang !== 'en',
    lat,
    lon
  }
}];

// Standardize description using Sarvam AI result or Domain Fallback Dictionary
const prev = $('2. Extract & Hash Phone (SHA-256)').first().json;
let englishText = prev.incoming_text;

try {
  const apiRes = $input.first().json;
  if (apiRes && apiRes.translated_text) {
    englishText = apiRes.translated_text;
  } else {
    throw new Error('Using dictionary fallback');
  }
} catch (err) {
  const dict = {
    'पानी बह रहा है': 'water is flowing',
    'पानी लीक हो रहा है': 'water is leaking',
    'पाइप टूट गया': 'pipe is broken',
    'सड़क पर पानी': 'water on the road',
    'स्कूल के पास': 'near the school',
    'தண்ணீர் கசிகிறது': 'water is leaking',
    'ನೀರು ಸೋರುತ್ತಿದೆ': 'water is leaking'
  };
  for (const [k, v] of Object.entries(dict)) {
    if (englishText.includes(k)) englishText = englishText.replace(k, v);
  }
  if (englishText === prev.incoming_text && prev.is_regional) {
    englishText = '[Citizen Leak Report in ' + prev.detected_language.toUpperCase() + ']: ' + prev.incoming_text;
  }
}

return [{
  json: {
    ...prev,
    description: englishText
  }
}];

const raw = $('1. WhatsApp / Telegram Webhook').first().json;
const body = raw.body || raw;

// Extract exact Telegram Chat ID
const chatId = (body.message && body.message.chat) ? body.message.chat.id : 
               (body.chat_id || (body.message && body.message.from ? body.message.from.id : null));

const lang = $('2. Extract & Hash Phone (SHA-256)').first().json.detected_language || 'en';
const reportId = Math.floor(1000 + Math.random() * 9000);
const zoneId = 'Z-001 (Ward 1)';
const desc = $('5. Format Standardized Description').first().json.description;

let message = `💧 NeerDrishti Smart Water Intelligence\n\n` +
  `✅ Water Leak Report Logged Successfully\n` +
  `📍 Matched Zone: ${zoneId}\n` +
  `📝 Description: ${desc}\n` +
  `🆔 Ticket Ref: #${reportId}\n` +
  `⏳ Status: Dispatched to Ward Repair Crew.`;

if (lang === 'hi') {
  message = `💧 नीरदृष्टि स्मार्ट जल खुफिया प्रणाली\n\n` +
    `✅ जल रिसाव रिपोर्ट सफलतापूर्वक दर्ज की गई\n` +
    `📍 जोन: ${zoneId}\n` +
    `📝 विवरण: ${desc}\n` +
    `🆔 टिकट संदर्भ: #${reportId}\n` +
    `⏳ स्थिति: वार्ड मरम्मत दल को भेज दी गई है।`;
}

return [{
  json: {
    status: 'success',
    chat_id: chatId,
    ticket_id: reportId,
    zone_id: zoneId,
    receipt_message: message
  }
}];

